repo.donations.py:
"""Donation records."""


class Donation:
    def __init__(self, donor, pounds):
        self.donor = donor
        self.pounds = pounds

    def __repr__(self):
        return "Donation(%r, %r)" % (self.donor, self.pounds)


ROWS = [('omar', 55), ('pia', 57), ('mia', 48), ('pia', 45), ('noor', 9), ('omar', 27)]


def load_donations():
    """Yield the stored donations one at a time."""
    for donor, pounds in ROWS:
        yield Donation(donor, pounds)

repo.register.py:
"""A book of donations with a cached total."""


class DonationBook:
    def __init__(self):
        self._donations = []
        self._total = None

    def add(self, donation):
        """Add one donation to the book."""
        self._donations.append(donation)

    def total(self):
        """Return the total pounds of the donations in the book."""
        if self._total is None:
            self._total = sum(x.pounds for x in self._donations)
        return self._total

    def count(self):
        """Return how many donations the book holds."""
        return len(self._donations)
